def IsCountableCoordinatePartition (B : CoordinateBlockIndex Γ → Set Γ) : Prop :=
  Pairwise (fun α β => Disjoint (B α) (B β)) ∧
    (∀ α, (B α).Countable) ∧ (⋃ α, B α) = Set.univ

